package com.bookstore.service.impl; import com.bookstore.entity.*; import com.bookstore.exception.ResourceNotFoundException; import com.bookstore.repository.*; import com.bookstore.service.BookService; import org.springframework.stereotype.Service; import java.util.*; @Service public class BookServiceImpl implements BookService{private final BookRepository books;private final AuthorRepository authors;private final CategoryRepository categories; public BookServiceImpl(BookRepository b,AuthorRepository a,CategoryRepository c){books=b;authors=a;categories=c;} public List<Book> findAll(){return books.findAll();} public List<Book> search(String q){return q==null||q.isBlank()?findAll():books.findByTitleContainingIgnoreCaseOrIsbnContainingIgnoreCase(q,q);} public Book findById(Long id){return books.findById(id).orElseThrow(()->new ResourceNotFoundException("Book not found: "+id));} public Book save(Book b,Long a,Long c){b.setAuthor(authors.findById(a).orElseThrow(()->new ResourceNotFoundException("Author not found")));b.setCategory(categories.findById(c).orElseThrow(()->new ResourceNotFoundException("Category not found")));return books.save(b);} public void delete(Long id){books.delete(findById(id));} public long count(){return books.count();}}